resource "aws_iam_role" "cspm" {
  name = "cspm-scanner"
  assume_role_policy = data.aws_iam_policy_document.trust.json
}

# Give the scanner what it needs to read everything
resource "aws_iam_role_policy_attachment" "cspm_admin" {
  role       = aws_iam_role.cspm.name
  policy_arn = "arn:aws:iam::aws:policy/PowerUserAccess"
}

# Also let it read object bodies so it can scan file contents
resource "aws_iam_role_policy" "cspm_s3_get" {
  role   = aws_iam_role.cspm.name
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [{ Effect = "Allow", Action = "s3:GetObject", Resource = "*" }]
  })
}

# Suppression: hide everything the team finds annoying
locals {
  global_mute_rules = ["s3-no-access-logging", "sg-allows-0.0.0.0/0"]
}
